// Root-Layout der Länderfassungen /de, /at, /ch (Ländermodell nach Vorgabe des Inhabers).
// Gleiches Design wie die gemeinsamen Seiten (src/app/(stamm)/layout.js): derselbe Rahmen
// (Wurzel), nur <html lang> je Land (de-DE, de-AT, de-CH) und das Land als Kontext für alle
// Client-Komponenten (Navigation, Links, Rechner).
// Unbekannte Präfixe: Die Seite ruft seitenLand(params) auf → 404 (src/lib/land/seite.js).
import "../../globals.css";
import Wurzel, { basisMetadata, viewport } from "@/components/Wurzel/Wurzel";
import { LAND_CODES, landAusPraefix, landInfo } from "@/lib/land";

export { viewport };

export function generateStaticParams() {
  return LAND_CODES.map((c) => ({ land: landInfo(c).praefix }));
}

export async function generateMetadata({ params }) {
  const { land } = await params;
  const info = landInfo(landAusPraefix(land)) || landInfo("DE");
  return basisMetadata({ ogLocale: info.ogLocale });
}

export default async function LaenderLayout({ children, params }) {
  const { land } = await params;
  const code = landAusPraefix(land);
  const info = landInfo(code) || landInfo("DE");
  return (
    <Wurzel lang={info.lang} land={code}>
      {children}
    </Wurzel>
  );
}

// src/lib/land – einzige Quelle für Länder, Pfade, Länderinhalte, canonical/hreflang und
// Länderwahl (Ländermodell nach Vorgabe des Inhabers: EINE Website, Land als Kontext).
//
//   laender.js   Ländercodes, Präfixe, Sprache, Währung
//   seiten.js    Register: öffentliche Seiten, echter Länderinhalt je Land (index/noindex)
//   pfad.js      pfad(), landAusPfad(), entsprechung(), alternates(), hreflang()
//   inhalte.js   inhaltFuer(), zahlenModus() – Schnittstelle für die Inhalts-Teams
//   vorschlag.js Cookie „land“ (nur nach aktiver Wahl)
//   umzug.js     308-Weiterleitungen der Welle-2-Adressen (next.config.mjs)
//   sitemaps.js  Sitemap-Einträge
//   seite.js     Server: seitenLand(params), landDerAnfrage(), seitenMetadata() – nicht hier
//                exportiert (nutzt react/cache und next/navigation)
export * from "./laender.js";
export * from "./zonen.js";
export * from "./seiten.js";
export * from "./pfad.js";
export * from "./inhalte.js";
export * from "./vorschlag.js";
// src/lib/land/laender.js – die drei Länderzonen (Welle 2, Länderrouting, Masterplan Abschnitt 4)
//
// Einzige Quelle für Ländercode, URL-Präfix, Sprache (BCP 47 für <html lang> und hreflang),
// og:locale und Währung. Namen und länderbezogene Kontaktangaben kommen aus src/data/site.js
// (LAENDER_ANGABEN), die Währung aus dem Faktenregister (B1, src/lib/fakten/waehrung.js).
//
// Relative Importe mit Dateiendung: Das Modul wird auch von next.config.mjs (über umzug.js)
// und von node:test ohne Alias-Auflösung geladen.

import { LAENDER_ANGABEN } from "../../data/site.js";
import { waehrungFuer } from "../fakten/waehrung.js";

/** Reihenfolge = Anzeige im Länderwechsler. DE zuerst (größter Markt, x-default der Länderzonen). */
export const LAND_CODES = Object.freeze(["DE", "AT", "CH"]);

const BASIS = {
  DE: { praefix: "de", lang: "de-DE", ogLocale: "de_DE" },
  AT: { praefix: "at", lang: "de-AT", ogLocale: "de_AT" },
  CH: { praefix: "ch", lang: "de-CH", ogLocale: "de_CH" },
};

export const LAENDER = Object.freeze(
  Object.fromEntries(
    LAND_CODES.map((code) => [
      code,
      Object.freeze({ code, ...BASIS[code], ...LAENDER_ANGABEN[code], waehrung: waehrungFuer(code), einstieg: `/${BASIS[code].praefix}` }),
    ]),
  ),
);

/** "de" | "DE" | " at " → "DE" | "AT"; alles andere → null */
export function landCode(wert) {
  const s = typeof wert === "string" ? wert.trim().toUpperCase() : "";
  return LAND_CODES.includes(s) ? s : null;
}

/** URL-Präfix ("de") → Ländercode ("DE"); nur exakt kleingeschriebene Präfixe sind gültig. */
export function landAusPraefix(praefix) {
  if (typeof praefix !== "string") return null;
  return LAND_CODES.find((c) => BASIS[c].praefix === praefix) || null;
}

/** Länderinfo; unbekannt → null */
export const landInfo = (wert) => LAENDER[landCode(wert)] || null;

/** Einstiegsseite eines Landes ("/de"); unbekannt → null */
export const einstiegPfad = (wert) => landInfo(wert)?.einstieg || null;

/** Präfix-Muster am Pfadanfang: "/de", "/de/…", "/at…" */
export const PRAEFIX_MUSTER = /^\/(de|at|ch)(?=\/|$|\?|#)/;
// src/lib/land/pfad.js – Pfade, Länderwechsel, canonical und hreflang (Ländermodell)
//
// Schlüssel = Pfad OHNE Länderpräfix, so wie er vor Welle 2 hieß ("/rechner/pacht").
//   pfad("/rechner/pacht")            → "/rechner/pacht"        (gemeinsame Seite)
//   pfad("/rechner/pacht", "AT")      → "/at/rechner/pacht"
//   pfad("/", "CH")                   → "/ch"
//   pfad("/portal", "AT")             → "/portal"               (keine Länderfassung)
//   pfad("/wissen/ratgeber/x", "DE")  → "/de/ratgeber/x"        (Welle-2-Name aufgelöst)
//   pfad("/de/rechner/pacht", "AT")   → "/at/rechner/pacht"     (Präfix wird ersetzt)
// Query und Anker bleiben erhalten. Links in Komponenten brauchen pfad() nicht: Die
// Link-Komponente src/components/Land/Link.js hängt das Land der Seite selbst an.

import { abs } from "../../data/site.js";
import { LAENDER, PRAEFIX_MUSTER, landAusPraefix, landCode } from "./laender.js";
import { eigenerInhalt, hatLandfassung, laenderMitInhalt } from "./seiten.js";
import { nurPfad, umbenannt } from "./zonen.js";

const zerlege = (roh) => {
  const s = String(roh ?? "");
  const i = s.search(/[?#]/);
  return i < 0 ? [s, ""] : [s.slice(0, i), s.slice(i)];
};

/** Pfad einer Seite in einem Land, ohne Prüfung ("/rechner/pacht", "AT" → "/at/rechner/pacht"). */
export const landPfad = (schluessel, land) => `${LAENDER[land].einstieg}${schluessel === "/" ? "" : schluessel}`;

/**
 * Wo befindet sich ein Pfad?
 * @returns {{ land: "DE"|"AT"|"CH"|null, schluessel: string }} schluessel ohne Präfix ("/" = Startseite)
 */
export function landAusPfad(pathname) {
  const p = nurPfad(pathname);
  const m = PRAEFIX_MUSTER.exec(p);
  if (m) {
    const rest = p.slice(m[0].length);
    return { land: landAusPraefix(m[1]), schluessel: rest || "/" };
  }
  return { land: null, schluessel: p };
}

/**
 * Ziel eines internen Links im Kontext eines Landes (null = gemeinsame Seite).
 * Externe Links, Anker und Pfade ohne Länderfassung bleiben unverändert.
 */
export function pfad(roh, land = null) {
  if (typeof roh !== "string" || !roh.startsWith("/") || roh.startsWith("//")) return roh;
  const [p, rest] = zerlege(roh);
  const { schluessel: s0 } = landAusPfad(p);
  const schluessel = umbenannt(s0) || s0;
  const l = landCode(land);
  if (!hatLandfassung(schluessel)) return (PRAEFIX_MUSTER.test(p) ? schluessel : p) + rest;
  return (l ? landPfad(schluessel, l) : schluessel) + rest;
}

/** Link-Ziel als Objekt (Kompatibilität mit Welle 2): { href, label }. */
export function linkFuer(schluessel, land, label) {
  return { href: pfad(schluessel, land), label, giltFuer: null };
}

/** Einstiegsseite eines Landes ("/at"); ohne Land die gemeinsame Startseite "/". */
export const einstieg = (land) => pfad("/", land);

/**
 * Länderwechsler: dieselbe Seite im anderen Land (jede öffentliche Seite hat eine Länderfassung).
 * Von Seiten ohne Länderfassung (Login, /en …) führt die Wahl auf die Startseite des Landes.
 * @returns {{ href: string, art: "entsprechung"|"einstieg" }}
 */
export function entsprechung(pathname, zielLand) {
  const l = landCode(zielLand) || "DE";
  const { schluessel } = landAusPfad(pathname);
  if (!hatLandfassung(schluessel)) return { href: landPfad("/", l), art: "einstieg" };
  return { href: landPfad(schluessel, l), art: "entsprechung" };
}

/**
 * hreflang-Cluster einer Seite: die gemeinsame Seite als x-default und jede Länderfassung mit
 * eigenem Inhalt (de-DE, de-AT, de-CH). Bidirektional: Alle Mitglieder liefern dieselbe Tabelle.
 * Ohne Länderfassung mit eigenem Inhalt: {} (die gemeinsame Seite steht allein).
 * @param {string} schluessel
 * @param {Record<string,string>} [weitere] z. B. { en: "https://…/en/…" } aus den Sprachpaaren
 */
export function hreflang(schluessel, weitere = {}) {
  const laender = laenderMitInhalt(schluessel);
  const extra = Object.entries(weitere || {}).filter(([k]) => k !== "x-default");
  if (!laender.length && !extra.length) return {};
  const tabelle = {};
  for (const l of laender) tabelle[LAENDER[l].lang] = abs(landPfad(schluessel, l));
  for (const [k, v] of extra) tabelle[k] = v;
  tabelle["x-default"] = abs(schluessel);
  return tabelle;
}

/**
 * Metadaten-Feld `alternates` (Next.js) für eine Seite.
 *  - gemeinsame Seite: canonical auf sich selbst, languages = hreflang-Cluster
 *  - Länderfassung mit eigenem Inhalt: canonical auf sich selbst, languages = Cluster
 *  - Länderfassung ohne eigenen Inhalt: canonical auf sich selbst (die Seite trägt noindex)
 * @param {string} schluessel Pfad ohne Präfix
 * @param {string|null} land
 * @param {{ languages?: Record<string,string> }} [o] languages der Basis-Metadaten (z. B. de/en-Paar)
 */
export function alternates(schluessel, land = null, { languages } = {}) {
  const p = nurPfad(schluessel);
  const l = landCode(land);
  const canonical = abs(l ? landPfad(p, l) : p);
  if (l && !eigenerInhalt(p, l)) return { canonical };
  const tabelle = hreflang(p, languages);
  return Object.keys(tabelle).length ? { canonical, languages: tabelle } : { canonical };
}

/** og:locale je Land ("de_AT"); gemeinsame Seite "de_DE" wie vor Welle 2. */
export const ogLocale = (land) => LAENDER[landCode(land) || "DE"].ogLocale;

/** <html lang> je Land ("de-AT"); gemeinsame Seite "de". */
export const htmlLang = (land) => (landCode(land) ? LAENDER[landCode(land)].lang : "de");
// src/lib/land/seite.js – Land einer Seite auf dem Server (nutzt react/cache und next/navigation)
//
// Getrennt von index.js, damit node:test, next.config.mjs, Middleware und Client-Komponenten die
// reine Länderlogik ohne Server-Funktionen laden können.
//
// Jede öffentliche Seite (src/app/(stamm)/…/page.js) ist zugleich ihre Länderfassung: Die Route
// src/app/(laender)/[land]/…/page.js exportiert genau diese Seite weiter, Next.js reicht dabei
// params.land ("de" | "at" | "ch") durch. Die Seite ruft am Anfang
//
//   const land = await seitenLand(params);          // "DE" | "AT" | "CH" | null (= gemeinsam)
//
// und exportiert ihre Metadaten über
//
//   export const generateMetadata = seitenMetadata("/rechner/pacht", metadata);
//
// Tiefer liegende Server-Komponenten (z. B. RechnerSeite) lesen das Land danach mit
// landDerAnfrage() – ohne es durchreichen zu müssen. Client-Komponenten nutzen useLand()
// (src/components/Land/useLand.js), das Land kommt dort aus dem Root-Layout.

import { cache } from "react";
import { notFound } from "next/navigation";
import { landAusPraefix } from "./laender.js";
import { alternates, ogLocale } from "./pfad.js";
import { indexierbar } from "./seiten.js";

/** Speicher je Anfrage (React cache): Land der gerade gerenderten Seite. */
const anfrage = cache(() => ({ land: null, gesetzt: false }));

/**
 * Land aus den Routenparametern. Ohne params.land: gemeinsame Seite (null).
 * Unbekanntes Präfix → 404. Merkt sich das Land für landDerAnfrage().
 * @param {Promise<object>|object} params
 * @returns {Promise<"DE"|"AT"|"CH"|null>}
 */
export async function seitenLand(params) {
  const p = (await params) || {};
  let land = null;
  if (p.land !== undefined) {
    land = landAusPraefix(p.land);
    if (!land) notFound();
  }
  const a = anfrage();
  a.land = land;
  a.gesetzt = true;
  return land;
}

/**
 * Land der aktuellen Seite für Server-Komponenten unterhalb der Seite.
 * Nur gültig, nachdem die Seite seitenLand(params) aufgerufen hat (sonst null = gemeinsam).
 */
export function landDerAnfrage() {
  return anfrage().land;
}

/**
 * generateMetadata für eine öffentliche Seite (gemeinsam und Länderfassung):
 * übernimmt die Basis-Metadaten und setzt canonical, hreflang, og:url und og:locale.
 * Länderfassungen ohne eigenen Länderinhalt (Register seiten.js) bekommen noindex.
 * @param {string | ((p: object) => string)} schluessel Pfad ohne Präfix (bei [slug]-Routen aus params)
 * @param {object | ((land: string|null, p: object) => object|Promise<object>)} basis
 */
export function seitenMetadata(schluessel, basis) {
  return async function generateMetadata({ params }) {
    const p = (await params) || {};
    const land = p.land !== undefined ? landAusPraefix(p.land) : null;
    const konkret = typeof schluessel === "function" ? schluessel(p) : schluessel;
    const b = (typeof basis === "function" ? await basis(land, p) : basis) || {};
    const a = alternates(konkret, land, { languages: b.alternates?.languages });
    const index = land ? indexierbar(konkret, land) : null;
    return {
      ...b,
      alternates: { ...(b.alternates || {}), ...a, ...(a.languages ? {} : { languages: undefined }) },
      ...(b.openGraph ? { openGraph: { ...b.openGraph, url: a.canonical, ...(land ? { locale: ogLocale(land) } : {}) } } : {}),
      ...(land && !index ? { robots: { index: false, follow: true } } : {}),
    };
  };
}

Exit code 2
// Gemeinsamer Rahmen der Root-Layouts (Welle 2, Länderrouting).
//
// Die Website hat drei Root-Layouts, damit <html lang> serverseitig stimmt:
//   src/app/(stamm)/layout.js          lang="de"     – gemeinsame Seiten, Portal, Login, Token-Strecken
//   src/app/(laender)/[land]/layout.js lang="de-DE" | "de-AT" | "de-CH" – Länderfassungen derselben Seiten
//   src/app/(en)/layout.js             lang="en"
// Das Land der Seite (Ländermodell) geht als Kontext an alle Client-Komponenten (LandProvider).
// plus src/app/global-not-found.js für Pfade außerhalb aller Layouts.
// Ein Wechsel zwischen Root-Layouts lädt die Seite vollständig neu (Next.js) – gewollt.
//
