  useEffect(() => {
    setGewaehlt(landAusCookie(document.cookie));
  }, [pfad]);
  const waehlen = useCallback((code) => {
    landWaehlen(code);
    setGewaehlt(code);
  }, []);
  return { pfad, land, routenLand: land, gewaehlt, waehlen };
}
