/** Bereiche ohne Länderfassung (Pfad gleich oder darunter). */
export const OHNE_LAND = Object.freeze([
  "/portal",
  "/login",
  "/registrieren",
  "/passwort-vergessen",
  "/einladung",
  "/angebot",
  "/bericht",
  "/p",
  "/api",
  "/design",
  "/en",
  "/termin/verwalten",
]);

/**
 * Technische Dateien der Website (Next.js-Metadaten-Routen, Bilder, Skripte). Sie sind keine
 * Seiten; die Linkprüfung ignoriert sie.
 */
export const TECHNISCH = Object.freeze(["/_next", "/img", "/geo", "/sitemap", "/robots.txt", "/manifest.webmanifest", "/llms.txt", "/icon", "/apple-touch-icon.png", "/favicon.ico", "/portal.webmanifest", "/sw-portal.js", "/portal-offline.html"]);

/**
 * Adressen aus dem Welle-2-Zwischenstand, die es so nicht mehr gibt (308 ohne Kette, umzug.js).
 * Der Ratgeber liegt wieder unter /ratgeber wie vor Welle 2.
 */
export const UMBENANNT = Object.freeze([{ alt: "/wissen/ratgeber", neu: "/ratgeber" }]);

const unter = (pfad, basis) => (basis === "/" ? pfad === "/" : pfad === basis || pfad.startsWith(`${basis}/`));

/** Pfad ohne Query und Anker, ohne abschließenden Schrägstrich; "" → "/" */
export function nurPfad(pfad) {
  const s = String(pfad ?? "").split(/[?#]/)[0];
  if (!s) return "/";
  return s.length > 1 ? s.replace(/\/+$/, "") || "/" : s;
}

/** Gehört der (präfixlose) Pfad zu einem Bereich ohne Länderfassung? */
export const ohneLand = (pfad) => {
  const p = nurPfad(pfad);
  return OHNE_LAND.some((b) => unter(p, b)) || TECHNISCH.some((b) => p === b || p.startsWith(b));
};

/** Welle-2-Adresse mit neuem Namen ("/wissen/ratgeber/x" → "/ratgeber/x"); sonst null */
export function umbenannt(pfad) {
  const p = nurPfad(pfad);
  for (const u of UMBENANNT) if (unter(p, u.alt)) return u.neu + p.slice(u.alt.length);
  return null;
}
// src/lib/land/vorschlag.js – Länderwahl-Cookie (Ländermodell nach Vorgabe des Inhabers)
//
// Grundsätze (Geoblocking-VO Art. 3 Abs. 2, Google: keine IP-basierte Anpassung):
//  - Es gibt KEINE Weiterleitung und keinen Vorschlag nach IP oder Sprache.
//  - Das Cookie „land“ wird erst bei aktiver Wahl gesetzt (Klick im Länderwechsler der Kopfleiste).
//  - Nur mit gesetztem Cookie leitet die Startseite „/“ auf das gewählte Land um (Middleware,
//    307, nie zwischengespeichert). Besucher ohne Cookie – auch Suchmaschinen – nie.
//  Kennzeichnung im Datenschutz-Entwurf: Prüfung Rechtsabteilung.

import { landCode } from "./laender.js";

/** Name und Laufzeit des Präferenz-Cookies (Prüfung Rechtsabteilung: Laufzeit 12 Monate). */
export const LAND_COOKIE = "land";
export const LAND_COOKIE_MAX_AGE = 60 * 60 * 24 * 365;

/** Land aus einem Cookie-String ("a=1; land=AT") – nur gültige Codes, sonst null. */
export function landAusCookie(cookieString) {
  if (typeof cookieString !== "string") return null;
  for (const teil of cookieString.split(";")) {
    const [k, ...v] = teil.trim().split("=");
    if (k === LAND_COOKIE) {
      try {
        return landCode(decodeURIComponent(v.join("=")));
      } catch {
        return null;
      }
    }
  }
  return null;
}

/** Cookie-Zeile für die aktive Länderwahl (nur nach Klick setzen). */
export function landCookieZeile(land, { https = true } = {}) {
  const code = landCode(land);
  if (!code) return null;
  return `${LAND_COOKIE}=${code}; Path=/; Max-Age=${LAND_COOKIE_MAX_AGE}; SameSite=Lax${https ? "; Secure" : ""}`;
}
// src/lib/land/umzug.js – Weiterleitungen der Welle-2-Adressen auf das Ländermodell
