  const quelle = readFileSync(q, "utf8");
  if (!/seitenLand\(params\)/.test(quelle)) fehler.push(`${k}: Seite ruft seitenLand(params) nicht auf`);
  if (!/seitenMetadata\(/.test(quelle)) fehler.push(`${k}: Metadaten nicht über seitenMetadata()`);
