  const ist = existsSync(ziel) ? readFileSync(ziel, "utf8").replace(/\r\n/g, "\n") : null;
  if (ist === soll) continue;
  if (pruefen) fehler.push(`${relative(WURZEL, ziel)} ${ist === null ? "fehlt" : "weicht ab"} (node scripts/landfassungen.mjs)`);
