  href: "/flaechencheck",
  cta: "Flächencheck starten",
};

function FeatureKachel({ feature, onNavigate }) {
  return (
    <Link
      href={feature.href}
      onClick={onNavigate}
      className="ov-noise group relative flex h-full flex-col justify-between overflow-hidden rounded-2xl bg-navy-950 p-6 text-white"
