export function enLandInhalt(schluessel, land) {
  const s = seiteFuer(schluessel);
  if (!s || !LAND_CODES.includes(land)) return false;
  return Object.hasOwn(EN_LAENDERINHALT[land], s.muster) && Object.hasOwn(LAENDERINHALT[land], s.muster) && uebersetzt(schluessel);
}
