1	// CookieDetails.js – Detailangaben zu einem Dienst im Cookie-Banner
2	import React from "react";
3	
4	const TEXTE = {
5	  de: { zweck: "Zweck:", anbieter: "Anbieter:", telefon: "Telefon", email: "E-Mail", dse: "Datenschutzerklärung des Anbieters", cookies: "Verwendete Cookies:", laufzeit: "Laufzeit", speicher: "Lokaler Speicher (Local Storage):", drittland: "Datenverarbeitung in Drittländern:", garantie: "Garantie für die Übermittlung:" },
6	  en: { zweck: "Purpose:", anbieter: "Provider:", telefon: "Phone", email: "Email", dse: "Provider's privacy policy", cookies: "Cookies used:", laufzeit: "duration", speicher: "Local storage:", drittland: "Data processing in third countries:", garantie: "Safeguard for the transfer:" },
7	};
8	
9	const CookieDetails = ({ service, sprache = "de" }) => {
10	  const t = sprache === "en" ? TEXTE.en : TEXTE.de;
11	  const kontakt = service?.contact || {};
12	  const laender = service?.dataProcessing?.countries || [];
13	  const mechanismen = service?.dataProcessing?.mechanisms || [];
14	  return (
15	    <div className="mt-3 p-4 bg-gray-50 rounded-lg text-sm space-y-3">
16	      <p>
17	        <strong>{t.zweck}</strong> {service?.purpose}
18	      </p>
19	
20	      <p className="font-medium mt-2">{t.anbieter}</p>
21	      <p>{service?.provider}</p>
22	      <ul className="list-disc pl-5 space-y-1">
23	        {kontakt.phone && <li>{t.telefon}: {kontakt.phone}</li>}
24	        {kontakt.email && <li>{t.email}: {kontakt.email}</li>}
25	        {kontakt.privacy && (
26	          <li>
27	            <a href={kontakt.privacy} target="_blank" rel="noopener noreferrer" className="text-navy-700 hover:underline">
28	              {t.dse}
29	            </a>
30	          </li>
31	        )}
32	      </ul>
33	
34	      {service?.cookies?.length > 0 && (
35	        <>
36	          <p className="font-medium mt-2">{t.cookies}</p>
37	          <ul className="list-disc pl-5 space-y-1">
38	            {service.cookies.map((cookie) => (
39	              <li key={cookie.name}>
40	                <strong>{cookie.name}</strong>
41	                {cookie.type ? ` · ${cookie.type}` : ""}
42	                {cookie.host ? ` · ${cookie.host}` : ""}
43	                {cookie.duration ? ` · ${t.laufzeit} ${cookie.duration}` : ""}
44	              </li>
45	            ))}
46	          </ul>
47	        </>
48	      )}
49	
50	      {service?.storage?.length > 0 && (
51	        <>
52	          <p className="font-medium mt-2">{t.speicher}</p>
53	          <ul className="list-disc pl-5 space-y-1">
54	            {service.storage.map((item) => (
55	              <li key={item.name}>
56	                <strong>{item.name}</strong> ({item.type}) – {item.host} – {item.duration}
57	              </li>
58	            ))}
59	          </ul>
60	        </>
61	      )}
62	
63	      {laender.length > 0 && (
64	        <p className="mt-2">
65	          <span className="font-medium">{t.drittland}</span> {laender.map((l) => l.name).join(", ")}
66	        </p>
67	      )}
68	
69	      {mechanismen.length > 0 && (
70	        <p className="mt-2">
71	          <span className="font-medium">{t.garantie}</span> {mechanismen.map((m) => m.name).join(", ")}
72	        </p>
73	      )}
74	    </div>
75	  );
76	};
77	
78	export default CookieDetails;

