content.content:
// Sprungnavigation der Startseite (UX-Audit P2-7): kompakte Chips direkt unter dem Hero.
// Mobil klebt die Leiste beim Scrollen unter dem Seitenkopf (68 px), ab md steht sie normal im Fluss.
// Server-Komponente, reine Anker-Links – funktioniert ohne JavaScript.

const ZIELE = [
  { id: "loesungen", label: "Lösungen" },
  { id: "boerse", label: "Börse" },
  { id: "energie", label: "Energie" },
  { id: "tools", label: "Tools" },
  { id: "faq", label: "FAQ" },
];

export default function Sprungnavigation() {
  return (
    <nav
      aria-label="Auf dieser Seite"
      className="sticky top-[68px] z-30 border-b border-ink-200/70 bg-white/90 backdrop-blur-xl backdrop-saturate-150 md:static md:bg-white md:backdrop-blur-none"
    >
      <ul className="ov-container flex gap-2 overflow-x-auto py-2.5 [scrollbar-width:none] md:justify-center md:py-3">
        {ZIELE.map((z) => (
          <li key={z.id} className="shrink-0">
            <a
              href={`#${z.id}`}
              className="flex min-h-10 items-center rounded-full bg-sand-50 px-4 text-[14px] font-semibold text-ink-800 ring-1 ring-ink-200/70 transition-colors hover:bg-ov-50 hover:text-ov-800 hover:ring-ov-200 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ov-500"
            >
              {z.label}
            </a>
          </li>
        ))}
      </ul>
    </nav>
  );
}
import { Factory, Hammer, Landmark, MapPinned, SunMedium } from "lucide-react";
import Stagger from "@/components/ui/Stagger";
import { GESELLSCHAFT, KENNZAHLEN } from "@/data/site";

/**
 * Vertrauensleiste direkt unter dem Hero.
 * Nur belegte Fakten (siehe docs/BRIEFING.md „Unternehmen“) – keine Kundenlogos,
 * keine Auszeichnungen, keine erfundenen Kennzahlen.
 */
const FAKTEN = [
  { icon: Factory, titel: "ÖKOVOLT Gruppe", text: `Photovoltaik seit ${KENNZAHLEN.gruppeGegruendet}` },
  { icon: SunMedium, titel: "Eigene Solarparks", text: "im Betrieb seit 2012" },
  { icon: Hammer, titel: "Eigene Rammtechnik", text: "Fundamente aus der Gruppe" },
  // Paket D: nicht „Projekte im gesamten DACH-Raum“ – belegt sind Gesellschaften in DE und AT
  // (Register siehe src/data/unternehmen.js); die Schweiz startet nur mit Daten und Werkzeugen (E11/E14).
  { icon: MapPinned, titel: "DE · AT", text: "Gesellschaften in Deutschland und Österreich" },
  { icon: Landmark, titel: GESELLSCHAFT.register, text: GESELLSCHAFT.gericht.replace("Landesgericht", "LG") },
];

export default function Vertrauensleiste() {
  return (
    <section aria-label="Fakten zur ÖkoInvest GmbH" className="border-b border-ink-100 bg-white">
      <div className="ov-container">
        <Stagger
          as="ul"
          schritt={70}
          className="grid grid-cols-2 gap-x-4 gap-y-5 py-7 sm:grid-cols-3 md:py-8 lg:grid-cols-5 lg:gap-0"
        >
          {FAKTEN.map((f, i) => (
            <li
              key={f.titel}
