const FAQ = [
  {
    q: "Was verdient man mit der Verpachtung einer Fläche für einen Solarpark?",
    a: `Für Freiflächen-Photovoltaik werden im DACH-Raum heute meist etwa ${fmt(PACHT.freiflaecheProHa.min)} bis ${fmt(PACHT.freiflaecheProHa.max)} € je Hektar und Jahr gezahlt – ein Vielfaches der landwirtschaftlichen Pacht. Entscheidend sind Netzanschluss, Größe, Lage in der EEG-Flächenkulisse und das Pachtmodell (fest, indexiert oder mit Umsatzbeteiligung). Der Flächencheck zeigt Ihnen die Spanne für Ihre Fläche.`,
